{
  "sql": "SELECT t1.product_category_name_english, ROUND(100.0 * SUM(CASE WHEN t2.payment_installments > 1 THEN 1 ELSE 0 END) / COUNT(DISTINCT t2.order_id), 2) AS pct_pagos_plazos FROM product_category_translation AS t1 INNER JOIN ( SELECT order_id, product_category_name, payment_installments FROM products AS t3 INNER JOIN order_items AS t4 ON t3.product_id = t4.product_id INNER JOIN order_payments AS t5 ON t4.order_id = t5.order_id WHERE t5.payment_type != 'not_defined' ) AS t2 ON t1.product_category_name = t2.product_category_name WHERE t2.payment_installments > 1 GROUP BY t1.product_category_name_english HAVING COUNT(DISTINCT t2.order_id) >= 100 ORDER BY pct_pagos_plazos DESC LIMIT 1"
}
